/*
 * Logic Analyzer Test
 * Generates 4 digital signals at different frequencies:
 *   D2 = 1 Hz   (500ms period)
 *   D3 = 2 Hz   (250ms period)
 *   D4 = 5 Hz   (100ms period)
 *   D5 = 10 Hz  (50ms period)
 *
 * Open the Logic Analyzer tab in the bottom panel.
 * Set CH1=D2, CH2=D3, CH3=D4, CH4=D5.
 * Press Run and observe the square waves!
 */

void setup() {
  pinMode(2, OUTPUT);
  pinMode(3, OUTPUT);
  pinMode(4, OUTPUT);
  pinMode(5, OUTPUT);
  Serial.println("Logic Analyzer Test — 4 channels");
}

void loop() {
  digitalWrite(2, HIGH);
  digitalWrite(3, HIGH);
  digitalWrite(4, HIGH);
  digitalWrite(5, HIGH);
  delay(50);

  digitalWrite(5, LOW);
  delay(50);

  digitalWrite(4, LOW);
  delay(50);

  digitalWrite(3, LOW);
  delay(50);

  digitalWrite(2, LOW);
  digitalWrite(3, HIGH);
  digitalWrite(4, HIGH);
  digitalWrite(5, HIGH);
  delay(50);

  digitalWrite(5, LOW);
  delay(50);

  digitalWrite(4, LOW);
  delay(50);

  digitalWrite(3, LOW);
  delay(50);
}
